<?php declare(strict_types=1);
function uc4(PDO $db,string $sql):int{try{return(int)$db->query($sql)->fetchColumn();}catch(Throwable){return 0;}}
$users=[];try{$users=$db->query('SELECT id,name,email,role,credits,daily_credits,plan,created_at FROM creator_users ORDER BY id DESC LIMIT 300')->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable){}
$total=uc4($db,'SELECT COUNT(*) FROM creator_users');$admins=uc4($db,"SELECT COUNT(*) FROM creator_users WHERE role IN ('admin','superadmin')");$credits=uc4($db,'SELECT COALESCE(SUM(credits),0) FROM creator_users');
?>
<div class="av4-page"><div class="av4-stat-grid"><div class="av4-stat"><b><?=number_format($total)?></b><span>Total users</span></div><div class="av4-stat purple"><b><?=number_format($admins)?></b><span>Admin accounts</span></div><div class="av4-stat blue"><b><?=number_format($credits)?></b><span>Credits held</span></div><div class="av4-stat green"><b><?=number_format(uc4($db,"SELECT COUNT(*) FROM creator_users WHERE created_at>=CURDATE()"))?></b><span>Joined today</span></div></div>
<div class="av4-card"><div class="av4-head"><div><h2>👥 Users & Credits</h2><p>Detailed account inventory with role and credit controls.</p></div><input id="uSearch" class="av4-search" placeholder="Search name, email, ID, role…"></div><div class="av4-table"><table id="uTable"><thead><tr><th>ID</th><th>Name</th><th>Email</th><th>Role</th><th>Credits</th><th>Daily</th><th>Plan</th><th>Created</th><th>Manage</th></tr></thead><tbody><?php foreach($users as $r):?><tr><td><?=av4h($r['id'])?></td><td><b><?=av4h($r['name'])?></b></td><td><?=av4h($r['email'])?></td><td><span class="av4-tag <?=in_array((string)$r['role'],['admin','superadmin'],true)?'purple':'gray'?>"><?=av4h($r['role'])?></span></td><td><?=number_format((int)$r['credits'])?></td><td><?=number_format((int)$r['daily_credits'])?></td><td><?=av4h($r['plan']??'—')?></td><td><?=av4h($r['created_at']??'')?></td><td><details><summary class="av4-summary">Edit</summary><form class="av4-mini-form" method="post" action="/smart-toolz/admin/admin-actions.php"><input type="hidden" name="action" value="user_role"><input type="hidden" name="back" value="users"><input type="hidden" name="csrf" value="<?=av4h(adminCsrf())?>"><input type="hidden" name="id" value="<?=av4h($r['id'])?>"><select name="role"><option value="user" <?=$r['role']==='user'?'selected':''?>>user</option><option value="admin" <?=$r['role']==='admin'?'selected':''?>>admin</option><option value="superadmin" <?=$r['role']==='superadmin'?'selected':''?>>superadmin</option></select><button class="av4-btn small">Role</button></form><form class="av4-mini-form" method="post" action="/smart-toolz/admin/admin-actions.php"><input type="hidden" name="action" value="user_credits"><input type="hidden" name="back" value="users"><input type="hidden" name="csrf" value="<?=av4h(adminCsrf())?>"><input type="hidden" name="id" value="<?=av4h($r['id'])?>"><input name="credits" type="number" min="0" value="<?=av4h($r['credits'])?>"><input name="daily_credits" type="number" min="0" value="<?=av4h($r['daily_credits'])?>"><button class="av4-btn primary small">Save credits</button></form></details></td></tr><?php endforeach;if(!$users):?><tr><td colspan="9" class="empty">No users found.</td></tr><?php endif;?></tbody></table></div></div></div><script>(function(){const i=document.getElementById('uSearch'),t=document.getElementById('uTable');if(i&&t)i.oninput=()=>{const s=i.value.toLowerCase();t.querySelectorAll('tbody tr').forEach(r=>r.style.display=r.innerText.toLowerCase().includes(s)?'':'none')};})();</script>
